/* hud_blobs.S , embedded GreenBoost overlay SPIR-V.
 *
 * Compiled shader lives in build/ (generated by `make hud-shader`).
 * Linked directly into libVkLayer_greenboost.so so the layer needs no
 * external .spv at runtime, same arrangement as nis_blobs.S.
 *
 * Symbols exported:
 *   gb_hud_spv_start / gb_hud_spv_end
 */

    .section .rodata,"a",%progbits

    .align 4
    .globl gb_hud_spv_start
    .type  gb_hud_spv_start, @object
gb_hud_spv_start:
    .incbin "build/gb_hud.spv"
    .globl gb_hud_spv_end
    .type  gb_hud_spv_end, @object
gb_hud_spv_end:

    .section .note.GNU-stack,"",%progbits
